  local WD = {"Sun","Mon","Tue","Wed","Thu","Fri","Sat"}
  draw_text(ox + 16, oy + 28, string.format("%s %d", WD[get_weekday() + 1], get_day()), 0xFFFF)
  draw_text_bold(ox + 16, oy + 12, string.format("%02d:%02d", get_hour(), get_minute()), 0xFFFF)
  draw_ring(ox + 168, oy + 28, 20, 15, 0.65, 0xEF5D, 0xFECE, 0x0000)
  -- custom code element (ox=ox + 0, oy=oy + 0)
  -- e.g. draw_text(ox + 4, oy + 4, "hi", 0xFFFF)
  -- ox/oy are already in scope here as this element's x/y.
end
